def agent(obs):
    try:
        s = obs.get("step")
        if s is None:
            s = int(obs.get("day", 0)) * 24 + int(obs.get("hour", 0))
        s = int(s)
        # REPLAY ALIGNMENT FIX: the action stored at step i of the
        # episode JSON was generated from the observation at step i-1
        # (its market effects are already visible at step i), so when
        # the agent receives obs at step s it must return ACTIONS[s+1].
        j = s + 1
        a = ACTIONS[j] if 0 <= j < len(ACTIONS) else (ACTIONS[-1] if ACTIONS else {})
        return {"farmer": a.get("farmer") or ["PASS"],
                "hands": a.get("hands") or [],
                "market": a.get("market") or []}
    except Exception:
        return {"farmer": ["PASS"], "hands": [], "market": []}
